import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`ebook-writer`,heroTitle:`Write your ebook in minutes`,heroSubtitle:`Perplexity Computer researches your topic, outlines every chapter, and writes a polished ebook draft — automatically.`,inputUrlCta:`Write my ebook`,inputUrlPlaceholder:`e.g. topic or URL`,inputUrlPrefill:`Go to {url} and do a deep analysis of the topic, audience, and content style. Then write me a complete ebook. 1) Research the subject thoroughly — key themes, subtopics, data points, and expert perspectives. 2) Create a detailed outline with 8-12 chapters, each with a compelling title and 3-5 key sections. 3) Write the full ebook — introduction, all chapters, and conclusion — in a clear, engaging voice that matches the tone and audience of the source material. 4) Add a table of contents, chapter summaries, and key takeaways per chapter. 5) Include actionable insights, examples, and data where relevant. 6) Format the final output as a clean, publishable document with consistent heading hierarchy, proper paragraph structure, and professional formatting ready for export to PDF or EPUB.`,heroOverlaySteps:[`Researching your topic and identifying key themes`,`Outlining chapters, structure, and narrative arc`,`Writing and refining each chapter with supporting research`,`Complete ebook draft with table of contents — ready to publish`],generatingSteps:[`Analyzing your topic to gather research, trends, and source material`,`Designing an agent to outline chapters, structure arguments, and draft compelling prose`,`Configuring research agents for fact-checking, citations, and supporting data`,`Setting up formatting, table of contents, and export-ready output`],featureSectionTitle:`From idea to published ebook`,featureCardTitles:[`Connects to your writing stack`,`Outputs you can publish`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Docs, Google Drive, Notion, Dropbox Sign, Canva — Computer drafts, formats, and stores your ebook across the tools you already use.`,`Full chapter drafts. Table of contents. Research citations. Author bio and book description. A polished manuscript ready for review or distribution.`],capabilitySectionTitle:`Your writing team, on autopilot`,capabilitySectionSubtitle:`Describe your ebook, step away, come back to a complete manuscript.`,capabilityCards:[{title:`Deep Research`,description:`Computer can research your topic across hundreds of sources — pulling statistics, quotes, case studies, and trends to ground every chapter in real data.`},{title:`Chapter Outlining`,description:`Computer can structure your ebook with a logical chapter flow — building narrative arcs, section breaks, and transitions that keep readers engaged.`},{title:`Manuscript Drafting`,description:`Computer can write full chapters in your chosen tone and style — from authoritative nonfiction to conversational how-to guides.`},{title:`Connect Your Tools`,description:`Computer can export to Google Docs, Google Drive, Notion, and Canva — build workflows across your entire writing and publishing stack.`},{title:`Remember Your Voice`,description:`Computer can remember your writing style, past chapters, and brand guidelines across sessions — so every ebook sounds unmistakably like you.`},{title:`Progress Tracking`,description:`Computer can monitor word counts, chapter completion, and revision status — and alert you when drafts are ready for review.`}]});export{t as default};
